{%- import 'authfly/components.html.j2' as af -%}
{%- set id = p.id or '' -%}{%- set l = p.labels or {} -%}{%- set error = p.error or '' -%}
{%- set formError = id ~ '-error' if error else none -%}
{%- set c8 -%}
{{ af.head(id, p.title or '', p.text or '') }}
{{ af.messages(id, error, p.info or '') }}
{%- set c1 -%}{{ l.account or '' }} {{ af.text('strong', 'font-semibold', {}, af_esc(p.account or '')) }}{%- endset -%}{{ af.text('', 'text-sm text-foreground', {'data-testid': 'account'}, c1) }}
{%- set c4 -%}{{ af.title(2, id ~ '-scopes', '', l.scopes or '') }}
{%- set c3 -%}{%- for s in p.scopes or [] -%}
{%- set c2 -%}{{ af.icon('check') }}{{ s.title or '' }}{%- endset -%}{{ af.box('li', 'flex items-center gap-2 text-sm text-foreground', {'data-scope': s.id or none}, c2) }}
{%- endfor -%}{%- endset -%}{{ af.box('ul', 'm-0 flex list-none flex-col gap-2 p-0', {'aria-labelledby': (id) ~ '-scopes' or none, 'data-testid': 'scopes'}, c3) }}{%- endset -%}{{ af.stack('2', '', '', '', {}, c4) }}
{%- set c7 -%}{%- set c5 -%}{{ af.hidden('csrf', p.csrf or '') }}
{{ af.hidden('decision', 'deny') }}
{{ af.button('', 'submit', af_skin('button', 'outline', 'w-full'), {}, af_esc(l.deny or '')) }}{%- endset -%}
{{ af.form(p.action or '', 'flex-1', {'data-testid': 'deny'}, c5) }}
{%- set c6 -%}{{ af.hidden('csrf', p.csrf or '') }}
{{ af.hidden('decision', 'approve') }}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {}, af_esc(l.approve or '')) }}{%- endset -%}
{{ af.form(p.action or '', 'flex-1', {'data-testid': 'approve'}, c6) }}{%- endset -%}{{ af.group('2', '', 'between', '', {}, c7) }}
{%- endset -%}
{{ af.card(af_skin('widgetCard'), {'data-testid': 'authfly-consent', 'data-client': p.client or '', 'aria-labelledby': none if p.landmarkLabel else id ~ '-title', 'aria-label': p.landmarkLabel or none}, c8) }}
